21	// NewACM creates a new ACM resource using the generic resource pattern.
22	func NewACM() AwsResource {
23		return NewAwsResource(&resource.Resource[ACMAPI]{
24			ResourceTypeName: "acm",
25			BatchSize:        10,
26			InitClient: WrapAwsInitClient(func(r *resource.Resource[ACMAPI], cfg aws.Config) {
27				r.Scope.Region = cfg.Region
28				r.Client = acm.NewFromConfig(cfg)
29			}),
30			ConfigGetter: func(c config.Config) config.ResourceType {
31				return c.ACM
32			},
33			Lister: listACMCertificates,
34			Nuker:  resource.SimpleBatchDeleter(deleteACMCertificate),
35		})
