38	// listACMCertificates retrieves all ACM certificates that match the config filters.
39	func listACMCertificates(ctx context.Context, client ACMAPI, scope resource.Scope, cfg config.ResourceType) ([]*string, error) {
40		var acmArns []*string
41	
42		// By default, ListCertificates only returns RSA_1024 and RSA_2048 certificates.
43		// Explicitly include all key types to ensure we find all certificates.
44		input := &acm.ListCertificatesInput{
45			Includes: &types.Filters{
46				KeyTypes: []types.KeyAlgorithm{
47					types.KeyAlgorithmRsa1024,
48					types.KeyAlgorithmRsa2048,
49					types.KeyAlgorithmRsa3072,
50					types.KeyAlgorithmRsa4096,
51					types.KeyAlgorithmEcPrime256v1,
52					types.KeyAlgorithmEcSecp384r1,
53					types.KeyAlgorithmEcSecp521r1,
54				},
55			},
56		}
57		paginator := acm.NewListCertificatesPaginator(client, input)
58	
59		for paginator.HasMorePages() {
60			page, err := paginator.NextPage(ctx)
61			if err != nil {
62				return nil, err
63			}
64	
65			for _, cert := range page.CertificateSummaryList {
66				if shouldIncludeACMCertificate(cert, cfg) {
67					acmArns = append(acmArns, cert.CertificateArn)
68				}
69			}
70		}
71	
72		return acmArns, nil
73	}
74	
75	// shouldIncludeACMCertificate determines if an ACM certificate should be included based on config filters.
76	func shouldIncludeACMCertificate(cert types.CertificateSummary, cfg config.ResourceType) bool {
77		if aws.ToBool(cert.InUse) {
78			logging.Debugf("ACM %s is in use, skipping", aws.ToString(cert.CertificateArn))
79			return false
80		}
81	
82		return cfg.ShouldInclude(config.ResourceValue{
83			Name: cert.DomainName,
84			Time: cert.CreatedAt,
85		})
86	}
87	
88	// deleteACMCertificate deletes a single ACM certificate.
89	func deleteACMCertificate(ctx context.Context, client ACMAPI, arn *string) error {
90		_, err := client.DeleteCertificate(ctx, &acm.DeleteCertificateInput{
91			CertificateArn: arn,
92		})
93		if err != nil {
94			return fmt.Errorf("failed to delete ACM certificate %s: %w", aws.ToString(arn), err)
95		}
96		return nil
97	}
