47	func listACMPCA(ctx context.Context, client ACMPCAAPI, scope resource.Scope, cfg config.ResourceType) ([]*string, error) {
48		var arns []*string
49	
50		paginator := acmpca.NewListCertificateAuthoritiesPaginator(client, &acmpca.ListCertificateAuthoritiesInput{})
51		for paginator.HasMorePages() {
52			page, err := paginator.NextPage(ctx)
53			if err != nil {
54				return nil, err
55			}
56	
57			for _, ca := range page.CertificateAuthorities {
58				if shouldIncludeACMPCA(ca, cfg) {
