67	// shouldIncludeACMPCA determines if an ACM PCA should be included based on config filters.
68	func shouldIncludeACMPCA(ca types.CertificateAuthority, cfg config.ResourceType) bool {
69		if ca.Status == types.CertificateAuthorityStatusDeleted {
70			return false
71		}
72	
73		// Use LastStateChangeAt as the reference time for time-based filters.
74		// Fall back to CreatedAt if the CA state was never changed.
75		referenceTime := aws.ToTime(ca.LastStateChangeAt)
76		if ca.LastStateChangeAt == nil {
77			referenceTime = aws.ToTime(ca.CreatedAt)
78		}
79	
80		return cfg.ShouldInclude(config.ResourceValue{Time: &referenceTime})
81	}
