83	// deleteACMPCA deletes a single ACM PCA certificate authority.
84	// This function handles the multi-step deletion process:
85	// 1. Describe the CA to get its current status
86	// 2. Disable the CA if it's in ACTIVE state (AWS requires this before deletion)
87	// 3. Delete the CA with a 7-day restoration period
88	func deleteACMPCA(ctx context.Context, client ACMPCAAPI, arn *string) error {
89		arnStr := aws.ToString(arn)
90	
91		logging.Debugf("Fetching CA details for ACMPCA %s", arnStr)
92		details, err := client.DescribeCertificateAuthority(ctx, &acmpca.DescribeCertificateAuthorityInput{
93			CertificateAuthorityArn: arn,
94		})
95		if err != nil {
96			return fmt.Errorf("failed to describe ACMPCA %s: %w", arnStr, err)
97		}
98		if details.CertificateAuthority == nil {
99			return fmt.Errorf("CA not found: %s", arnStr)
100		}
101		if details.CertificateAuthority.Status == "" {
102			return fmt.Errorf("CA status unavailable: %s", arnStr)
103		}
104	
105		// AWS requires ACTIVE CAs to be disabled before deletion.
106		// CAs in CREATING, PENDING_CERTIFICATE, DISABLED, or DELETED states can be deleted directly.
107		if needsDisableBeforeDelete(details.CertificateAuthority.Status) {
108			logging.Debugf("Disabling ACMPCA %s before deletion", arnStr)
109			if _, err = client.UpdateCertificateAuthority(ctx, &acmpca.UpdateCertificateAuthorityInput{
110				CertificateAuthorityArn: arn,
111				Status:                  types.CertificateAuthorityStatusDisabled,
112			}); err != nil {
113				return fmt.Errorf("failed to disable ACMPCA %s: %w", arnStr, err)
114			}
115		}
116	
117		_, err = client.DeleteCertificateAuthority(ctx, &acmpca.DeleteCertificateAuthorityInput{
118			CertificateAuthorityArn:     arn,
119			PermanentDeletionTimeInDays: aws.Int32(permanentDeletionDays),
120		})
121		if err != nil {
122			return fmt.Errorf("failed to delete ACMPCA %s: %w", arnStr, err)
123		}
124	
125		logging.Debugf("Deleted ACMPCA: %s", arnStr)
