39	func listDataPipelines(ctx context.Context, client DataPipelineAPI, scope resource.Scope, cfg config.ResourceType) ([]*string, error) {
40		var identifiers []*string
41	
42		paginator := datapipeline.NewListPipelinesPaginator(client, &datapipeline.ListPipelinesInput{})
43		for paginator.HasMorePages() {
44			page, err := paginator.NextPage(ctx)
45			if err != nil {
46				// Data Pipeline service doesn't exist in many regions. The SDK
47				// fails with a DNS resolution error ("no such host") when
48				// attempting to connect. Treat this as an empty result.
49				if strings.Contains(err.Error(), "no such host") {
50					logging.Debugf("[data-pipeline] service not available in region %s, skipping", scope.Region)
51					return nil, nil
52				}
53				return nil, err
54			}
55	
56			var pipelineIds []string
57			for _, p := range page.PipelineIdList {
58				pipelineIds = append(pipelineIds, aws.ToString(p.Id))
59			}
60			if len(pipelineIds) == 0 {
61				continue
62			}
63	
64			// DescribePipelines accepts max 25 IDs per call
65			for i := 0; i < len(pipelineIds); i += describePipelinesBatchSize {
66				end := min(i+describePipelinesBatchSize, len(pipelineIds))
67	
68				descOutput, err := client.DescribePipelines(ctx, &datapipeline.DescribePipelinesInput{
69					PipelineIds: pipelineIds[i:end],
70				})
71				if err != nil {
72					return nil, err
73				}
74	
75				for _, desc := range descOutput.PipelineDescriptionList {
76					pipelineID := aws.ToString(desc.PipelineId)
77					name := aws.ToString(desc.Name)
78	
79					rv := config.ResourceValue{Name: &name}
80					for _, field := range desc.Fields {
81						if aws.ToString(field.Key) == "@creationTime" {
82							rv.Time, _ = util.ParseTimestamp(field.StringValue)
83							break
84						}
85					}
86	
87					if cfg.ShouldInclude(rv) {
88						identifiers = append(identifiers, aws.String(pipelineID))
89					}
90				}
91			}
92		}
93	
94		return identifiers, nil
95	}
